INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine serielle Schnittstelle immer schneller als parallele Übertragung ist?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Implementierung"}, {"text": "Ja", "correct": false, "because": "Parallele kann bei niedrigen Frequenzen Vorteile haben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Version der Schnittstelle bietet bis zu 6 Gbit/s Übertragungsrate?', 3, '[{"text": "SATA 3.0", "correct": true, "because": "Standard für 6 Gbit/s"}, {"text": "SATA 2.0", "correct": false, "because": "Nur 3 Gbit/s"}, {"text": "SATA 1.0", "correct": false, "because": "Nur 1,5 Gbit/s"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen unterstützt die Schnittstelle?', 5, '[{"text": "Hot-Swapping", "correct": true, "because": "Erlaubt Austausch im Betrieb"}, {"text": "Native Command Queuing", "correct": true, "because": "Optimiert Zugriffe"}, {"text": "Grafikverarbeitung", "correct": false, "because": "Keine Grafikfunktion"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Nur Speicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Schnittstelle ersetzte PATA. b) Sie benötigt dickere Kabel als PATA.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Kabel sind dünner"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Speichergeräts?', 4, '[{"text": "Schnittstellengeschwindigkeit", "correct": false, "because": "Beeinflusst Leistung"}, {"text": "Kompatibilität", "correct": false, "because": "Entscheidend für Nutzung"}, {"text": "Gehäusefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Schnittstelle Hot-Swapping unterstützt?', 2, '[{"text": "Ja", "correct": true, "because": "Erlaubt Austausch im Betrieb"}, {"text": "Nein", "correct": false, "because": "Hot-Swapping ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft verbessert die Effizienz von Festplattenzugriffen?', 4, '[{"text": "Native Command Queuing", "correct": true, "because": "Optimiert Reihenfolge"}, {"text": "Port-Multiplier", "correct": false, "because": "Für Mehrfachverbindungen"}, {"text": "Caching", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Schnittstelle langsamer als NVMe ist. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "NVMe nutzt PCIe, schneller"}, {"text": "Nein", "correct": false, "because": "SATA bis 6 Gbit/s, NVMe bis 32 Gbit/s"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Benötigt jede Verbindung ein eigenes Kabel?', 2, '[{"text": "Ja", "correct": true, "because": "Punkt-zu-Punkt-Verbindung"}, {"text": "Nein", "correct": false, "because": "Keine geteilte Verbindung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte sind typischerweise mit der Schnittstelle kompatibel?', 5, '[{"text": "Festplatten", "correct": true, "because": "Standard für HDDs"}, {"text": "SSDs", "correct": true, "because": "Häufig genutzt"}, {"text": "Grafikkarten", "correct": false, "because": "Nutzen PCIe"}, {"text": "Netzwerkkarten", "correct": false, "because": "Andere Schnittstellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl eines Speichers?', 4, '[{"text": "Kompatibilität mit Mainboard", "correct": true, "because": "Sichert Funktion"}, {"text": "Kabeldesign", "correct": false, "because": "Sekundär"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Schnittstelle unterstützt 3,3 V Stromversorgung. b) Sie ersetzt immer NVMe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, NVMe ist Alternative"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Speicherverbindung?', 3, '[{"text": "Datenkabel", "correct": false, "because": "Überträgt Daten"}, {"text": "Stromkabel", "correct": false, "because": "Versorgt Gerät"}, {"text": "LED-Anzeige", "correct": true, "because": "Nur optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich die Geschwindigkeit einer Verbindung prüfe?', 4, '[{"text": "SATA-Version des Mainboards kontrollieren", "correct": true, "because": "Bestimmt maximale Rate"}, {"text": "Kabel farblich prüfen", "correct": false, "because": "Irrelevant"}, {"text": "Festplatte wiegen", "correct": false, "because": "Kein Geschwindigkeitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Schnittstelle für externe Geräte ungeeignet ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "eSATA für externe Geräte"}, {"text": "Ja", "correct": false, "because": "eSATA ermöglicht externe Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature verbessert die Datenübertragung?', 4, '[{"text": "Advanced Host Controller Interface", "correct": true, "because": "Optimiert Zugriffe"}, {"text": "IDE-Modus", "correct": false, "because": "Eingeschränkte Funktionen"}, {"text": "Bluetooth", "correct": false, "because": "Andere Technologie"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat die Schnittstelle dünnere Kabel als PATA?', 2, '[{"text": "Ja", "correct": true, "because": "Vereinfacht Verkabelung"}, {"text": "Nein", "correct": false, "because": "PATA nutzt breite Flachkabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Schnittstelle gegenüber älteren Standards?', 5, '[{"text": "Höhere Geschwindigkeit", "correct": true, "because": "Bis 6 Gbit/s"}, {"text": "Hot-Swapping", "correct": true, "because": "Erlaubt Austausch im Betrieb"}, {"text": "Größere Speicherkapazität", "correct": false, "because": "Abhängig von Gerät"}, {"text": "Bessere Grafik", "correct": false, "because": "Kein Grafikfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Installation eines Speichers unwichtig?', 3, '[{"text": "Kabelverbindung", "correct": false, "because": "Notwendig für Funktion"}, {"text": "Port-Kompatibilität", "correct": false, "because": "Sichert Anschluss"}, {"text": "Gerätegewicht", "correct": true, "because": "Kein Installationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich ein Speichergerät anschließe?', 4, '[{"text": "Daten- und Stromkabel verbinden", "correct": true, "because": "Sichert Betrieb"}, {"text": "Nur Stromkabel nutzen", "correct": false, "because": "Fehlt Datenübertragung"}, {"text": "Gerät bemalen", "correct": false, "because": "Irrelevant"}]');
